    #[inline(always)]
    fn slide_i32x8<const SHIFT: usize>(self, a: i32x8<Self>, b: i32x8<Self>) -> i32x8<Self> {
        if SHIFT >= 8usize {
            return b;
        }
        let result = cross_block_alignr_256x1(
            self,
            Bytes::to_bytes(b).val.0,
            Bytes::to_bytes(a).val.0,
            SHIFT * 4usize,
        );
        Bytes::from_bytes(u8x32 {
            val: crate::support::Aligned256(result),
            simd: self,
        })
    }
    #[inline(always)]
    fn slide_within_blocks_i32x8<const SHIFT: usize>(
        self,
        a: i32x8<Self>,
        b: i32x8<Self>,
    ) -> i32x8<Self> {
        if SHIFT >= 4usize {
            return b;
        }
        let result = dyn_alignr_256(
            self,
            Bytes::to_bytes(b).val.0,
            Bytes::to_bytes(a).val.0,
            SHIFT * 4usize,
        );
        Bytes::from_bytes(u8x32 {
            val: crate::support::Aligned256(result),
            simd: self,
        })
    }
    #[inline(always)]
    fn count_ones_i32x8(self, a: i32x8<Self>) -> i32x8<Self> {
        crate::kernel!(
            #[inline(always)]
            fn kernel(token: Avx2, a: i32x8<Avx2>) -> i32x8<Avx2> {
                let value = a.into();
                let nibble_mask = _mm256_set1_epi8(0x0f);
                let lookup = _mm256_setr_epi8(
                    0, 1, 1, 2, 1, 2, 2, 3, 1, 2, 2, 3, 2, 3, 3, 4, 0, 1, 1, 2, 1, 2, 2, 3, 1, 2,
                    2, 3, 2, 3, 3, 4,
                );
                let low = _mm256_and_si256(value, nibble_mask);
                let high = _mm256_and_si256(_mm256_srli_epi16::<4>(value), nibble_mask);
                let byte_counts = _mm256_add_epi8(
                    _mm256_shuffle_epi8(lookup, low),
                    _mm256_shuffle_epi8(lookup, high),
                );
                _mm256_madd_epi16(
                    _mm256_maddubs_epi16(byte_counts, _mm256_set1_epi8(1)),
                    _mm256_set1_epi16(1),
                )
                .simd_into(token)
            }
        );
        kernel(self, a)
    }
